void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  test(
    'real aomenc 64x64 mono keyframe w/ directional+angle_delta+edge-filter: '
    'HW luma recon == SW pre-filter (bit-exact)',
    timeout: const Timeout(Duration(minutes: 90)),
    () async {
      const sbSize = 64;
      const maxLeaves = 16;
      const miBits = 5; // bitLength(64/4)
      const coeffN = 256; // 16x16

      // Sanity: the stream really exercises the directional+angle path (SW oracle).
      expect(
        _dirCount,
        greaterThan(0),
        reason: 'stream has directional leaves',
      );
      expect(
        _deltaCount,
        greaterThan(0),
        reason: 'stream has nonzero angle_delta',
      );
      expect(
        _z1Real,
        greaterThan(0),
        reason: 'stream has a z1 leaf reading REAL top-right extension',
      );
      expect(_leafCount, equals(16));

      final recon = HarborIntraReconWalkSeq(
        sbSize: sbSize,
        maxLeaves: maxLeaves,
        maxLog2: 2,
        edgeFilter: true,
        name: 'recon',
      );
      final rClk = SimpleClockGenerator(10).clk;
      final rReset = Logic(name: 'rreset');
      final rStart = Logic(name: 'rstart');
      final rLeafCount = Logic(
        name: 'rleafcount',
        width: recon.input('leaf_count').width,
      );
      final rPositions = Logic(
        name: 'rpositions',
        width: maxLeaves * 2 * miBits,
      );
      final rLog2 = Logic(name: 'rlog2', width: maxLeaves * 2);
      final rYModes = Logic(name: 'rymodes', width: maxLeaves * 4);
      final rYAngles = Logic(name: 'ryangles', width: maxLeaves * 3);
      final rTxTypes = Logic(name: 'rtxtypes', width: maxLeaves * 4);
      final rCoeffs = Logic(name: 'rcoeffs', width: maxLeaves * coeffN * 16);
      final rEnEdge = Logic(name: 'renedge');
      recon.input('clk').srcConnection! <= rClk;
      recon.input('reset').srcConnection! <= rReset;
      recon.input('start').srcConnection! <= rStart;
      recon.input('leaf_count').srcConnection! <= rLeafCount;
      recon.input('positions').srcConnection! <= rPositions;
      recon.input('log2sizes').srcConnection! <= rLog2;
      recon.input('y_modes').srcConnection! <= rYModes;
      recon.input('y_angles').srcConnection! <= rYAngles;
      recon.input('tx_types').srcConnection! <= rTxTypes;
      recon.input('coeffs').srcConnection! <= rCoeffs;
      recon.input('enable_edge_filter').srcConnection! <= rEnEdge;
      await recon.build();

      rReset.inject(1);
      rStart.inject(0);
      rLeafCount.inject(_leafCount);
      rPositions.inject(_positions);
      rLog2.inject(_log2v);
      rYModes.inject(_ymodes);
      rYAngles.inject(_yangles);
      rTxTypes.inject(_txv);
      rCoeffs.inject(_coeffs);
      rEnEdge.inject(_enEdge ? 1 : 0);
      Simulator.setMaxSimTime(2000000000);
      unawaited(Simulator.run());
      await rClk.nextPosedge;
      rReset.inject(0);
      await rClk.nextPosedge;
      rStart.inject(1);
      await rClk.nextPosedge;
      rStart.inject(0);
      var guard = 0;
      while (recon.output('done').value.toInt() != 1) {
        await rClk.nextPosedge;
        if (++guard > 2000000) fail('recon timeout');
      }
      final frame = recon.output('frame').value.toBigInt();
      int px(int r, int c) =>
          ((frame >> ((r * sbSize + c) * 8)) & BigInt.from(0xff)).toInt();

      var firstDiff = '';
      var diffs = 0;
      for (var r = 0; r < 64; r++) {
        for (var c = 0; c < 64; c++) {
          final want = _swY[r * 64 + c];
          if (px(r, c) != want) {
            diffs++;
            firstDiff = firstDiff.isEmpty
                ? 'first diff @($r,$c): HW=${px(r, c)} SW=$want'
                : firstDiff;
          }
        }
      }
      expect(
        diffs,
        equals(0),
        reason: '$diffs/4096 luma pixels differ; $firstDiff',
      );
      await Simulator.endSimulation();
    },
  );
}
